begin;
create table public.blocks (blocker_id uuid references public.profiles(id), blocked_id uuid references public.profiles(id), primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
alter table public.blocks enable row level security;
grant select,insert,delete on public.blocks to authenticated;
create policy blocks_own on public.blocks for all to authenticated using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
create function public.can_contact(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$ select not exists(select 1 from blocks where (blocker_id=a and blocked_id=b) or (blocker_id=b and blocked_id=a)); $$;
revoke all on function public.can_contact(uuid,uuid) from public; grant execute on function public.can_contact(uuid,uuid) to authenticated;
create policy conversations_unblocked on public.conversations as restrictive for insert to authenticated with check(public.can_contact(buyer_id,seller_id));
create policy messages_unblocked on public.messages as restrictive for insert to authenticated with check(exists(select 1 from public.conversations c where c.id=conversation_id and public.can_contact(c.buyer_id,c.seller_id)));
create table public.appointments (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id), proposer_id uuid not null references public.profiles(id), place text not null check(length(place) between 3 and 200), meet_at timestamptz not null, status text not null default 'proposed' check(status in ('proposed','accepted','cancelled','completed')), buyer_done boolean not null default false, seller_done boolean not null default false, created_at timestamptz default now());
alter table public.appointments enable row level security;
grant select on public.appointments to authenticated;
create policy appointments_read on public.appointments for select to authenticated using(exists(select 1 from public.conversations c where c.id=conversation_id and auth.uid() in(c.buyer_id,c.seller_id)));
create function public.propose_meeting(thread uuid,location text,meeting_time timestamptz) returns uuid language plpgsql security definer set search_path=public as $$ declare c conversations; result uuid; begin select * into c from conversations where id=thread for update; if c.id is null or auth.uid() is null or auth.uid() not in(c.buyer_id,c.seller_id) or not public.can_contact(c.buyer_id,c.seller_id) then raise exception 'Không có quyền hẹn gặp'; end if; if meeting_time<=now() or meeting_time>now()+interval '90 days' then raise exception 'Chọn giờ hẹn trong 90 ngày tới'; end if; if exists(select 1 from appointments where conversation_id=thread and status in('proposed','accepted')) then raise exception 'Đã có lịch hẹn đang mở'; end if; insert into appointments(conversation_id,proposer_id,place,meet_at) values(thread,auth.uid(),trim(location),meeting_time) returning id into result; return result; end; $$;
create function public.respond_meeting(meeting uuid,action text) returns void language plpgsql security definer set search_path=public as $$ declare a appointments; c conversations; begin select * into a from appointments where id=meeting for update; select * into c from conversations where id=a.conversation_id; if c.id is null or auth.uid() is null or auth.uid() not in(c.buyer_id,c.seller_id) then raise exception 'Không có quyền'; end if; if action='accept' and a.status='proposed' and a.proposer_id<>auth.uid() and a.meet_at>now() then update appointments set status='accepted' where id=meeting; elsif action='cancel' and a.status in('proposed','accepted') then update appointments set status='cancelled' where id=meeting; elsif action='complete' and a.status='accepted' then update appointments set buyer_done=buyer_done or auth.uid()=c.buyer_id,seller_done=seller_done or auth.uid()=c.seller_id where id=meeting; update appointments set status='completed' where id=meeting and buyer_done and seller_done; if exists(select 1 from appointments where id=meeting and status='completed') then update listings set status='sold' where id=c.listing_id; end if; else raise exception 'Thao tác không hợp lệ'; end if; end; $$;
create table public.reviews (id uuid primary key default gen_random_uuid(),appointment_id uuid references public.appointments(id),reviewer_id uuid references public.profiles(id),reviewee_id uuid references public.profiles(id),rating int not null check(rating between 1 and 5),body text not null check(length(body) between 3 and 1000),created_at timestamptz default now(),unique(appointment_id,reviewer_id));
alter table public.reviews enable row level security; grant select on public.reviews to anon,authenticated;
create policy reviews_read on public.reviews for select using(true);
create function public.leave_review(meeting uuid,stars int,comment text) returns void language plpgsql security definer set search_path=public as $$ declare a appointments;c conversations;begin select * into a from appointments where id=meeting;select * into c from conversations where id=a.conversation_id;if a.status<>'completed' or c.id is null or auth.uid() is null or auth.uid() not in(c.buyer_id,c.seller_id) then raise exception 'Chỉ đánh giá sau khi hai bên xác nhận giao dịch';end if;insert into reviews(appointment_id,reviewer_id,reviewee_id,rating,body) values(meeting,auth.uid(),case when auth.uid()=c.buyer_id then c.seller_id else c.buyer_id end,stars,trim(comment));end;$$;
create table public.moderators(user_id uuid primary key references public.profiles(id));alter table public.moderators enable row level security;
create function public.is_moderator() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from moderators where user_id=auth.uid()); $$;
alter table public.reports add column resolved boolean not null default false;
create policy reports_moderator on public.reports for select to authenticated using(public.is_moderator());
create table public.moderation_log(id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.profiles(id),report_id uuid references public.reports(id),action text not null,created_at timestamptz default now());alter table public.moderation_log enable row level security;
create function public.resolve_report(report uuid,hide_listing boolean) returns void language plpgsql security definer set search_path=public as $$ declare r reports; begin if not public.is_moderator() then raise exception 'Chỉ quản trị viên';end if;select * into r from reports where id=report for update;if r.id is null then raise exception 'Không tìm thấy báo cáo';end if;if hide_listing then update listings set status='hidden' where id=r.listing_id;end if;update reports set resolved=true where id=report;insert into moderation_log(actor_id,report_id,action) values(auth.uid(),report,case when hide_listing then 'hide_listing' else 'resolve' end);end;$$;
revoke all on function public.propose_meeting(uuid,text,timestamptz),public.respond_meeting(uuid,text),public.leave_review(uuid,int,text),public.is_moderator(),public.resolve_report(uuid,boolean) from public;
grant execute on function public.propose_meeting(uuid,text,timestamptz),public.respond_meeting(uuid,text),public.leave_review(uuid,int,text),public.is_moderator(),public.resolve_report(uuid,boolean) to authenticated;
commit;
-- Moderation cannot be undone by a listing owner.
alter table public.listings add column moderated boolean not null default false;
revoke update on public.listings from authenticated;
grant update(title,description,price,category,area,status) on public.listings to authenticated;
create policy listings_visible on public.listings as restrictive for select using(not moderated or owner_id=auth.uid() or public.is_moderator());
create policy conversations_visible on public.conversations as restrictive for insert to authenticated with check(exists(select 1 from public.listings l where l.id=listing_id and not l.moderated));
create or replace function public.resolve_report(report uuid,hide_listing boolean) returns void language plpgsql security definer set search_path=public as $$ declare r reports; begin if not public.is_moderator() then raise exception 'Chỉ quản trị viên';end if;select * into r from reports where id=report for update;if r.id is null then raise exception 'Không tìm thấy báo cáo';end if;if hide_listing then update listings set status='hidden',moderated=true where id=r.listing_id;end if;update reports set resolved=true where id=report;insert into moderation_log(actor_id,report_id,action) values(auth.uid(),report,case when hide_listing then 'hide_listing' else 'resolve' end);end;$$;
grant execute on function public.is_moderator() to anon;
